import { useCallback, useId, useRef, useState, type KeyboardEvent } from 'react';
import { JxInput, JxTag } from '@jinx-ui/react';

// NOTE: из README подтверждён только экспорт JxButton/JxModal. Имена JxInput/JxTag
// и проп onRemove у тега — предположение по конвенции jx-*; сверьте с d.ts пакета.

export interface TagPickerProps {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
}

const SEPARATORS = [',', ';'];

function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  maxTags,
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const listId = useId();
  const inputRef = useRef<HTMLInputElement>(null);

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const tag = raw.trim().replace(/\s+/g, ' ');
      if (!tag) return;
      if (maxTags !== undefined && tags.length >= maxTags) return;
      if (tags.some((t) => t.toLowerCase() === tag.toLowerCase())) {
        setDraft('');
        return;
      }
      commit([...tags, tag]);
      setDraft('');
    },
    [commit, maxTags, tags],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((t) => t !== tag));
      inputRef.current?.focus();
    },
    [commit, tags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || SEPARATORS.includes(event.key)) {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const atLimit = maxTags !== undefined && tags.length >= maxTags;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
      <JxInput
        ref={inputRef}
        label={label}
        placeholder={atLimit ? 'Достигнут лимит тегов' : placeholder}
        value={draft}
        disabled={atLimit}
        aria-describedby={listId}
        onValueChange={setDraft}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
      />

      <ul
        id={listId}
        aria-label="Выбранные теги"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-space-2)',
          margin: 0,
          padding: 0,
          listStyle: 'none',
        }}
      >
        {tags.map((tag) => (
          <li key={tag.toLowerCase()}>
            <JxTag onRemove={() => removeTag(tag)} aria-label={`Тег ${tag}`}>
              {tag}
            </JxTag>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default TagPicker;

